import {mkdir,readFile,rename,writeFile} from 'node:fs/promises';
import path from 'node:path';
export function createStore(root){const file=path.join(root,'incidents.json');async function load(){try{const data=JSON.parse(await readFile(file,'utf8'));if(!Array.isArray(data))throw new Error('incidents.json must contain an array');return data}catch(e){if(e.code==='ENOENT')return [];throw e}}async function save(items){await mkdir(root,{recursive:true});const tmp=`${file}.${process.pid}.tmp`;await writeFile(tmp,JSON.stringify(items,null,2),'utf8');await rename(tmp,file)}return {load,save,file}}

