import http from 'node:http';
import {mkdir} from 'node:fs/promises';
import path from 'node:path';
import {randomUUID} from 'node:crypto';
import {createStore} from './store.js';
import {createIncidentService} from './service.js';
import {requestId,withRequestContext} from './context.js';
const port=Number(process.env.PORT??3000);
const dataDir=path.resolve(process.env.DATA_DIR??'./data');
if(!Number.isInteger(port)||port<1||port>65535)throw new Error('invalid PORT');
await mkdir(dataDir,{recursive:true});
const service=createIncidentService(createStore(dataDir));
function json(res,status,body){res.writeHead(status,{'content-type':'application/json; charset=utf-8','cache-control':'no-store','x-request-id':requestId()??'unknown'});res.end(JSON.stringify(body))}
async function body(req){const chunks=[];let size=0;for await(const chunk of req){size+=chunk.length;if(size>100*1024){const e=new Error('payload too large');e.statusCode=413;throw e}chunks.push(chunk)}try{return JSON.parse(Buffer.concat(chunks).toString('utf8'))}catch{const e=new Error('invalid JSON');e.statusCode=400;throw e}}
const server=http.createServer((req,res)=>{const id=req.headers['x-request-id']?.toString()||randomUUID();withRequestContext(id,async()=>{const u=new URL(req.url,`http://${req.headers.host||'localhost'}`);try{if(req.method==='GET'&&u.pathname==='/health')return json(res,200,{status:'ok'});if(req.method==='GET'&&u.pathname==='/incidents')return json(res,200,{incidents:await service.list()});if(req.method==='POST'&&u.pathname==='/incidents')return json(res,201,await service.create(await body(req)));return json(res,404,{error:'not found'})}catch(e){return json(res,e.statusCode??400,{error:e.message})}}).catch(e=>{console.error(JSON.stringify({level:'error',requestId:id,message:e.message}));if(!res.headersSent)json(res,500,{error:'internal error'});else res.destroy()})});
server.requestTimeout=30000;server.headersTimeout=10000;server.listen(port,()=>console.log(JSON.stringify({level:'info',event:'listening',port,dataDir})));
let stopping=false;function shutdown(signal){if(stopping)return;stopping=true;console.log(JSON.stringify({level:'info',event:'shutdown_requested',signal}));const deadline=setTimeout(()=>{console.error('shutdown deadline exceeded');process.exitCode=1},5000);server.close(e=>{clearTimeout(deadline);if(e){console.error(e);process.exitCode=1}else console.log(JSON.stringify({level:'info',event:'shutdown_complete'}))})}
process.once('SIGTERM',()=>shutdown('SIGTERM'));process.once('SIGINT',()=>shutdown('SIGINT'));

