import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdtemp,rm} from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import {createStore} from '../src/store.js';
import {createIncidentService} from '../src/service.js';
test('creates and persists an incident',async()=>{const dir=await mkdtemp(path.join(os.tmpdir(),'incident-'));try{const s=createIncidentService(createStore(dir),()=> '2026-01-01T00:00:00.000Z');const item=await s.create({title:'Database latency',severity:'high'});assert.equal(item.status,'open');assert.equal((await s.list()).length,1)}finally{await rm(dir,{recursive:true,force:true})}});
test('rejects short titles',async()=>{const dir=await mkdtemp(path.join(os.tmpdir(),'incident-'));try{const s=createIncidentService(createStore(dir));await assert.rejects(s.create({title:'x'}),/at least 3/)}finally{await rm(dir,{recursive:true,force:true})}});
